-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[27220] = { id = 27220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim into the deep part of Tidefury Cove to the southwest. Let me know how it works!", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", objectives = "Smear Pagle's Fish Paste, Extra Strength on yourself, then swim into Tidefury Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27221] = { id = 27221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", objectives = "Speak with Major Mills at the docks in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27222] = { id = 27222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", completion = "Well done, {name}! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!", objectives = "Use the mortars to defeat Tethyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27223] = { id = 27223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retribution", description = "Where Market Row meets Festival Lane, you will encounter The Unforgiven. If you slay the entirety of Crusaders' Square, you will coax out Timmy the Cruel. Both of these former champions committed heinous acts against innocents here in the name of gaining unholy power.\n\nYou must destroy both of them and rid Stratholme of their foul presence. Take caution, for they were powerful fighters in life, and their new dark powers will only have made them even more deadly.", progress = "Show them no mercy.", completion = "You may have this as a suitable reward. I found it nestled in the armor of one of the scourge here.", objectives = "Kill The Unforgiven and Timmy the Cruel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27224] = { id = 27224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andorhal Phase Flag" }
quests[27225] = { id = 27225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Signilda Hardforge", description = "Signilda Hardforge has sent word that she wishes to honor you for your mastery of arms and your dedication to the Alliance. Make your way to Stormwind, and speak with her at the Training Hall to the south of Old Town. I do not know what she has planned, but it sounds like she has been impressed with your rapid progress.", completion = "It's good to see that you received my message. I have something important I wish to discuss with you.", objectives = "Speak to Signilda Hardforge at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27226] = { id = 27226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hair of the Dog", description = "Thank the Warchief that you're here, {name}. I've made a critical error with the sea dogs and need your help to rectify the situation.\n\nYou see, I sent them out against the worgen coming from Fenris Isle stone cold sober. They attacked the beasts and promptly got their butts handed to them. Many of them died, but a few still live, barely clinging on to dear life.\n\nTake this barrel of ale to the Decrepit Fields, east of here, and force it down the throats of fallen sea dogs.", completion = "A-HA! I knew it! Lesson learned, I suppose. We will not fail again. I will be sure to have some ale on hand at the front lines.", objectives = "Rouse 8 Orc Sea Dogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27227] = { id = 27227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Aurius Rivendare", description = "This Chapel is the last Light amongst so much darkness. Ras Frostwhisper took his own life in the slaughterhouse, carving his face into a macabre smile in front of the Lich King, who raised him into the Lich that now haunts Scholomance.\n\nThe ground where that atrocity occured is now Scourge holy ground, blessed by the Lich King with the very darkest magic. Lord Aurius Rivendare, new ruler of Stratholme, now guards it and continues his master's evil work. Slay him without pause.", progress = "Don't waste our time. Every second spend chatting away is a second we aren't taking Stratholme back for the Light.", completion = "Stratholme will become a paragon of all that is good in this world. You have my thanks for your part in this mission.", objectives = "Kill Lord Aurius Rivendare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27228] = { id = 27228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man Against Abomination", description = "Deep within, you will find Ramstein the Gorger. I cannot bear to tell you the atrocities this monster has commited. Know only this - he deserves to feel the full wrath of countless lost souls, a wrath you will bring upon him.\n\nHave no mercy. Be unwavering in your fury.", completion = "I respect the power you demonstrated in killing Ramstein. With proper rage backing your actions, I think even the Scourge can know fear.", objectives = "Slaughter Ramstein the Gorger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27229] = { id = 27229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SMASH BROODQUEEN", description = "<The following is written in very large print.>\n\nSPIDERS IN NORTH CAVE BAD. POISON OGRES. OGRES GET SICK. BAD!\n\nBIG BIG SPIDER IN CAVE MAKE MORE SPIDERS. MORE SPIDERS BAD!\n\nKILL BIG SPIDER, STOP MORE SPIDERS. KILL BIG SPIDER, GET BIG PRIZE! GOOD!\n\n<A crude drawing accompanies this.>", progress = "Are you here about the sign?\n\nI don't want to talk about it unless you've got proof of a kill.", completion = "By Grom, I'm glad that's over with. If you read that sign you may have some idea how desperate I got after trying to communicate to these lumbering oafs.", objectives = "Obtain the Broodqueen Pedipalp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27230] = { id = 27230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons for War", description = "The Scourge are adept at forging powerful armaments for their soldiers, making it difficult for our men to kill 'em! There are blacksmithing plans near the Baroness Anastari's ziggurat that their chief swordsmith plans to use for an extremely powerful weapon for Lord Aurius.\n\nWe're going to prevent that weapon from being made and stop their regular arms flow with one blow! Go take the plans and kill the Black Guard Swordsmith when he comes to defend 'em, and it'll make our mission much easier.", progress = "You need to kill their swordsmith! Go!", completion = "Great! Without a steady flow of their weapons, we'll win through attrition!", objectives = "Kill the Black Guard Swordsmith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27231] = { id = 27231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements from Fenris", description = "Those that survived your assault on Fenris managed to drink the blood of the wolf. They turned into ferocious worgen, hell-bent on vengeance. Now they paddle across Lordamere Lake and assault my sea dogs. Many have already been killed. The worgen monsters must be stopped!\n\nMake your way to the Decrepit Fields, east of here, and kill the Hillsbrad worgen that infest the area. Once you've killed them all, make your way to the Horde communication panel, located at the docks. I'll be in touch.", progress = "Report?", completion = "<Hatchet's communication device crackles.>\n\nHatchet here, are they all dead?", objectives = "Kill 10 Hillsbrad Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27232] = { id = 27232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waters Run Red...", description = "<The communication console hums.>\n\nThose worgen you killed were the scouting party. There are hundreds more incoming! Looks like Crowley and Bloodfang made the blood offering to every human in Lordaeron.\n\nGet in one of those Horde cannons and send them all back to their makers. Let the waters of Lordamere Lake run red with their blood!", completion = "Though you killed a large number of the newly turned worgen, many more are sure to appear. Still, their assault will have softened. Well done, {name}!", objectives = "Kill 50 Hillsbrad Worgen with the Horde Cannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27233] = { id = 27233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "I can handle training from here.  If you're looking for something else to do, I recommend heading up the road to the northwest.  The Cenarion druids and Argent Crusade have a small camp set up there, at Dalson's old farm.  Maybe they can keep you busy until we need your help again.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27234] = { id = 27234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas... the symbol of the Defias!\n\nThe reports indicate their leader resides on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.", objectives = "Obtain the Defias Orders from Garn Mathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27235] = { id = 27235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", progress = "Well met, {class}. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo.", objectives = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27236] = { id = 27236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secondhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work.", objectives = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27237] = { id = 27237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here....", objectives = "Collect 1 Salvaged Strongbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27238] = { id = 27238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, {name}. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. Now, we must confirm your findings. The implications are too great if we are wrong.", objectives = "Speak with Lady Jaina Proudmoore in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27239] = { id = 27239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the mystery of the Defias' involvement in this kidnapping.", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias have allied themselves with HER? The traitor?\n\n<Lady Jaina composes herself and prepares to explain.>", objectives = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27240] = { id = 27240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to Grand Admiral Jes-Tereth in Stormwind castle that the Defias are the ones who carried out the Varian's kidnapping. I have little doubt that Stormwind's armies will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", completion = "So it was the Defias who served as the hands of Onyxia in this plot?\n\n<The admirall's face grows red with anger and her hands clench into fists.>\n\nYou and Lady Jaina have done Stormwind a great service this day. The traitors will not live long enough to regret their crimes.", objectives = "Speak with Jaina to travel to Stormwind and meet with Grand Admiral Jes-Tereth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27241] = { id = 27241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Jaina", description = "We must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", completion = "I have no doubt that the king meant every word when he told you he plans to destroy the Defias once and for all. He does not make promises lightly, and the enemies of Stormwind should know it.", objectives = "Return to Lady Jaina Proudmoore in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27242] = { id = 27242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture Bloodfen raptors or Bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them.", objectives = "Use the Sturdy Rope to capture 6 Bloodfen Raptors or Bloodfen Screechers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27243] = { id = 27243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two.", objectives = "Place the Raptor Bait near the windmill in Blackhoof Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27244] = { id = 27244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, {name}.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...", objectives = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27245] = { id = 27245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, {class}, just bring back my men alive.", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men.", objectives = "Collect Grimtotem Keys from the Grimtotem Tauren in Blackhoof Village and use them to free 5 Theramore Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27246] = { id = 27246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!", objectives = "Bring the Spy's Report to Lieutenant Aden in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27247] = { id = 27247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Vimes", description = "Captain Vimes should see the orc report you found, {name}.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says...", objectives = "Bring the Spy's Report to Captain Garran Vimes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27248] = { id = 27248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27249] = { id = 27249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the monsters who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates.", objectives = "Speak to Inspector Tarem at the Shady Rest Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27250] = { id = 27250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BAD COPY", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?", sourceObjective = "Speak with Vincent Hyal in Menethil Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27251] = { id = 27251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble.", objectives = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27252] = { id = 27252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.", objectives = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27253] = { id = 27253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. I had a man placed in that inn as a spy and I don't trust in the competence of these humans to uncover what happened.\n\nWhatever you find, don't give a scrap of it to that investigator. We'll handle this ourselves.", completion = "<The inspector regards you with what can only be disdain and distrust.>\n\nLeave this place be, errand boy, or I'll be sure to bring a contingent of guard with me next time to sink the lesson home.", objectives = "Investigate the Shady Rest Inn in at the border of the Barrens in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27254] = { id = 27254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", progress = "What's that you have there, {name}? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?", objectives = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27255] = { id = 27255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", progress = "Something for me, {class}?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, {name}.\n\nYou should know that.", objectives = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27256] = { id = 27256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, {name}. Now I rip them open and pour them onto the shield...", objectives = "Collect 5 Acidic Venom Sacs from Darkmist spiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27257] = { id = 27257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything...", objectives = "Speak with Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27258] = { id = 27258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", progress = "Hello there, {class}. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, {name}. I craft so many different shields and sets of armor, I can't keep track of them all.", objectives = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27259] = { id = 27259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27260] = { id = 27260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "Hmm... now this is interesting.", objectives = "Bring Reethe's Badge to Krog in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27261] = { id = 27261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.", objectives = "Go with Ogron to speak with Reethe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27262] = { id = 27262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27263] = { id = 27263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that.", objectives = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27264] = { id = 27264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", completion = "Hello, {name}. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book.", objectives = "Find out more about Reethe from Adjutant Tesoran in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27265] = { id = 27265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ezul'aan Calls", description = "Ezul'aan, one of the foremost paladins in the realm, has asked to speak with you personally. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.\n\nYou should make your way to Stormwind immediately and meet him at the Training Hall in the Old Town district.", completion = "It heartens me to see that my message found you, {name}. We have much to discuss.", objectives = "Speak to Ezul'aan at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27266] = { id = 27266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalgrun Calls", description = "Dalgrun Steelpine oversees the training and coordination of hunters in the service of Stormwind. He has asked to speak to you personally. As soon as you are able, travel to Stormwind and meet with Dalgrun at the Training Hall in Old Town.\n\nI have no idea what he has planned, but it sounds like he has been impressed with your rapid progress.", completion = "Ah, you've arrived. Make yourself at home, {name}. We have much to discuss.", objectives = "Speak to Dalgrun Steelpine in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27267] = { id = 27267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Contact with SI:7", description = "It seems that the leaders of SI:7 have taken an interest in your progress and your service to the Alliance. Veruca Darkstream, a high ranking member of SI:7, has asked to speak with you. Veruca is awaiting your arrival at the Training Hall in Stormwind.\n\nI'm not sure what she wants with you, but it seemed important.", completion = "I hope my message didn't unnerve you, {name}. I have called you here to recognize your accomplishments.", objectives = "Speak with Veruca Darkstream at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27268] = { id = 27268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrice Lancaster Sends Word", description = "I have an urgent message for you from Stormwind, {name}. It seems that Speak to Patrice Lancaster has asked to speak with you at the Training Hall in Stormwind's Old Town district. The messenger did not say what the matter concerned, but that you should travel to Stormwind with all haste.", completion = "It heartens me to see that you received my message and responded so quickly.", objectives = "Speak to Patrice Lancaster at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27269] = { id = 27269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of the Moon", description = "I have an urgent message for you from Darnassus. The message is from the High Priestess of Elune, Tyrande Whisperwind, herself! The messenger did not say what the matter concerned, but that you should travel to the Temple of the Moon in Darnassus and meet with the high priestess at once.", completion = "Welcome to the Temple of the Moon, {name}. I am glad that you chose to answer my summons so quickly.", objectives = "Speak to Tyrande Whisperwind at the Temple of the Moon in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27270] = { id = 27270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with Mulric", description = "I have an urgent message for you from Stormwind, {name}. It seems Mulric Boldrock has asked to speak with you the next time you're in the city.\n\nThe messenger gave no explanation for the shaman's invitation, but you should travel to Stormwind and find Mulric Boldrock at the Training Hall to the south of Old Town as soon as you can.", completion = "Welcome, {name}. I am glad that you decided to accept my invitation.", objectives = "Speak with Mulric Boldrock at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27271] = { id = 27271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frazzle's Request", description = "I just received a message from Stormwind, {name}. One of Stormwind's most renowned mages, Frazzle Frostfingers, has requested that you visit him at the Training Hall in Stormwind. The Training Hall is located in the Old Town district of Stormwind.\n\nI do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", completion = "Welcome to the Wizard's Sanctum, {name}. I have been watching your progress with interest.", objectives = "Speak with Frazzle Frostfingers at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27272] = { id = 27272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message From Evelyn Thorn", description = "It seems that the elders in our ranks have taken notice of your progress and dedication, {name}. Evelyn Thorn, one of the oldest and most respected members of our circle, has sent word that she wishes to speak with you. You should not take such an invitation lightly. Most only speak with her in the course of their lessons, but if she has asked to see you personally, it must be an important matter.\n\nHurry back to Stormwind and look for her at the Training Hall to the south of the Old Town district.", completion = "I see that my message managed to reach you. Good. We have much to discuss.", objectives = "Speak with Evelyn Thorn at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27273] = { id = 27273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation from Moonglade", description = "You just missed the messenger from Moonglade, {name}. He said little, except that he carried an urgent message from Loganaar, one of the honored trainers of the Cenarion Circle. Head to Moonglade as quickly as you can, {name}. The matter sounds important.\n\nLook for Loganaar in the village of Nighthaven.", completion = "I'm glad to see that you have arrived safely in Nighthaven, {name}. I offer you the welcome and the hospitality of the Cenarion Circle.", objectives = "Speak to Loganaar at Nighthaven in Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27274] = { id = 27274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrice Lancaster Sends Word", description = "I have an urgent message for you from Stormwind, {name}. Patrice Lancaster has asked to meet with you in Stormwind. The message didn't say what the priest trainer wanted to discuss, but you should make your way to Stormwind as quickly as you can. Look for Patrice Lancaster at the Training Hall in the Old Town district of the city.", completion = "I see that you received my message. Excellent!", objectives = "Speak to Patrice Lancaster at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27275] = { id = 27275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together Again", description = "We saw to it that the sentinel was healed and re-equipped. I already sent her back into the field.\n\nHead back up and go to Darkcloud Pinnacle. She'll meet you there.", completion = "Good to see you again, {name}. Let us put the fear of the Goddess into the Grimtotem.", objectives = "Speak with the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27276] = { id = 27276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together Again", description = "We saw to it that the brave was healed and re-equipped. I already sent him back into the field.\n\nHead back up and go to Darkcloud Pinnacle. He'll meet you there.", completion = "I am honored by your presence, {name}. Let us put the fear of the Earth Mother into the Grimtotem.", objectives = "Speak with the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27277] = { id = 27277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with Feenix Arcshine", description = "I've received an urgent message from Orgrimmar for you, {name}. The renowned mage, Feenix Arcshine, wants you to meet with him in Orgrimmar. I'm not sure what this is about, but if I was you, I would travel to the capital as fast as possible and seek out Feenix Arcshine at The Barracks in the Valley of Honor.", completion = "Ah, good. It seems my message did find you.", objectives = "Speak with Feenix Arcshine at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27278] = { id = 27278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tamanji's Call", description = "A courier from Orgrimmar just delivered a message for you. I'm to tell you that Tamanji, master of the hunters in Orgrimmar, has asked to meet with you.\n\nTravel quickly to Orgrimmar and present yourself to Tamanji at The Barracks in the Valley of Honor.", completion = "Good, you're here. Let's get started.", objectives = "Speak with Tamanji at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27279] = { id = 27279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Hand", description = "A messenger just arrived from Orgrimmar bearing a communication for you. Thega Graveblade, the senior rogue trainer in Orgrimmar, has sent for you. You must head to Orgrimmar immediately and meet with her at The Barracks in the Valley of Honor.\n\nWhen Thega Graveblade summons you, the prudent thing to do is obey. Do not keep her waiting, {name}.", completion = "Now that you are here, we can begin.", objectives = "Speak with Thega Graveblade at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27280] = { id = 27280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Riverspeaker Calls", description = "News travels upon the winds, young shaman. Your deeds have not gone unnoticed! It seems Hretar Riverspeaker wishes to discuss something with you. Make your way to Orgrimmar as quickly as you can and speak with him at The Barracks in the Valley of Honor. He will be among the others who offer training.", completion = "I see you are both obedient and talented, {name}. Stay that way, and you will go far in the Horde.", objectives = "Speak with Hretar Riverspeaker at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27281] = { id = 27281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok Ogrefist", description = "I just received word that you are needed in Orgrimmar, {name}. Gormok Ogrefist, the honored trainer of warriors in the city, has sent for you. It would not be wise to ignore such a summons.\n\nTravel quickly to Orgrimmar and visit The Barracks in the Valley of Honor where Gormok awaits your arrival.", completion = "I see you are both obedient and talented, {name}. Stay that way, and you will go far in the Horde.", objectives = "Speak with Gormok Ogrefist at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27282] = { id = 27282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kazak's Behest", description = "{name}, I have received word that you are needed back in Orgrimmar. Kazak Darkscream, one of the senior warlock trainers, has something important that he wishes to discuss with you. It seems like the kind of thing that cannot wait.\n\nMake your way back to Orgrimmar and speak with him as soon as you can. You will find him at the Training Hall in the Valley of Honor.", completion = "Ah, you're here at last.", objectives = "Speak with Kazak Darkscream at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27283] = { id = 27283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Journey to Moonglade", description = "As you have heard, Moonglade is the home of the Cenarion Circle, the brotherhood of druids. All who dwell there do so in the peace of Cenarius. It is in that spirit that the trainer Loganaar has extended an invitation to visit him in Moonglade.\n\nYou will find him in the village of Nighthaven.", completion = "Welcome to Moonglade, {name}. I have been looking forward to meeting you.", objectives = "Speak with Loganaar in Nighthaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27284] = { id = 27284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "I'm sorry I can't be of much help, {name}, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work.", objectives = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27285] = { id = 27285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.", objectives = "Speak with Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27286] = { id = 27286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance.", objectives = "Return the information about Reethe to Captain Garran Vimes in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27287] = { id = 27287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, {name}. He may be a tough nut to crack.", completion = "Did Vimes send you? Couldn't do his dirty work himself, could he...", objectives = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27288] = { id = 27288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.", objectives = "Speak with Captain Garran Vimes in Theramore about Reethe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27289] = { id = 27289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vimes's Report", description = "You've done some good work, {name}, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.", objectives = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27290] = { id = 27290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Forsaken Forward Command", description = "The time has come to destroy Crowley, Bloodfang and every dog at their command. To do this, though, will require cunning and planning the likes of which they would never dare dream!\n\nAs one of my most trusted soldiers, {name}, I need you to go to Forsaken Forward Command, located in Gilneas, and report to Deathstalker Commander Belmont. I have sent Belmont ahead with my plans. He awaits your arrival.\n\nArthura will escort you to Forward Command. Tell me when you are ready and I will send you on your way.", completion = "Well if it isn't Seamannub!\n\nI hope you're ready for battle, because that's all you'll find in this hellhole. We're at the heart of contested territory and these worgen mongrels won't give an inch!", objectives = "Report to Deathstalker Commander Belmont at Forsaken Forward Command in Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27291] = { id = 27291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the stones in the graveyard just north of Theramore's gates.", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand.", objectives = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27292] = { id = 27292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.", objectives = "Speak with Krog at Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27293] = { id = 27293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. We knew nothing of these plans and we lost a good man because of it. I don't trust that we're not next on their list.", objectives = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27294] = { id = 27294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm led to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.", objectives = "Collect 7 Blackhoof Armaments from Blackhoof Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27295] = { id = 27295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.", objectives = "Speak with Tabetha at her farm in the Quagmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27296] = { id = 27296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. If I know him, he'll appreciate the taste of vengeance.", objectives = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27297] = { id = 27297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh, though I get the impression you probably don't mind that. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nGo tell your leader that his vengeance has been sated.", completion = "<Krog listens to your report.>\n\nI'm impressed, {name}. I would've thought that the Grimtotem criminals would've been more difficult to locate. The Alliance are truly incompetent.\n\nIn truth, I just sought to answer the death of one of my men, but this situation has been more fortunate than expected. If the Grimtotem choose to retaliate, it will likely be against the Alliance. Perhaps we will soon have the manpower to drive the scum from these shores once and for all.", objectives = "Return to Krog at Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27298] = { id = 27298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Avaros Dawnglaive", description = "Avaros Dawnglaive, a senior Blood Knight and advisor to the warchief, requires your presence in Orgrimmar. He has taken an interest in your training, {name}, and it is imperative that you speak with him immediately.\n\nThe message I received didn't mention the reason he requested your visit, but you should set out for Orgrimmar right away. Avaros Dawnglaive can be found at The Barracks in the Valley of Honor.", completion = "I've heard much about you, {name}. You have a bright future ahead of you in the Horde.", objectives = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27299] = { id = 27299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torn Ground", description = "It won't be takin' much convincin' to turn us against da Twilight - dat's already our goal. We've already come to battle here though, so we may be needin' ya help before we can turn towards dere fortress.\n\nDa Twilight have already brought Iso'rath up from da ground to the south, I'm sure ya noticed. Its tentacles have been burstin' from da ground all around us. We could use a hand beatin' them down if you be willin'.", progress = "Did ya have any luck with dose tentacles?", completion = "Tank ya, {class}. A bit of breathin' room helps a lot.", objectives = "Kill 3 Tentacles of Iso'rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27300] = { id = 27300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Back", description = "Da Twilight's Hammer have destroyed a Dragonmaw town to the south and are performin' dey're summonin' rituals from there. Offer dem no respite to continue wit dey're incantations. Bring tha battle to dem!", completion = "Revenge is bittersweet, but I'm glad we be havin' someone as powerful as you do see dis done.", objectives = "Kill 12 Twilight's Hammer at the Ruins of Drakgor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27301] = { id = 27301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbroken", description = "We are preparing a ritual that may be of use in destroying Iso'rath, the old god bred abomination that the Twilight's Hammer have brought up from the depths. We are delayed though, for one of our strongest was captured during an assault on their encampment.\n\nEarthcaller Yevaa is within the ruins to the south. She is not dead. I am sure of it. Please, rescue her. If any of us is deserving of your aid, it is her.", completion = "Thank the elements that you've come. Did my brothers send you?", objectives = "Find Earthcaller Yevaa within the Ruins of Drakgor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27302] = { id = 27302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Solutions", description = "I'm new to this gig. Very new. But ya know what? That gives me perspective!\n\nThese shaman buddies of mine have come upon somethin' great, but they're too single minded! They lean on the elements and they forget to make use of the common materials all around them.\n\nIn the ruins to the south, I saw those Twilight goons tote in barrels of flammable oil! They used it when they razed the town. I say we use it when we raze them.", progress = "I wonder what happens when you douse an elemental with that stuff. Jumbo-super-bonfire-elemental? I'm thinkin' so. We'll have to try.", completion = "Now that's what I'm talkin' about! Can you think of all the uses for this stuff? I definitely can't. But I can think of a lot, and I'm liking the possibilities.", objectives = "Gather 10 barrels of Pyreburn Oil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27303] = { id = 27303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Bound", description = "It goes without saying that I had no desire to stay here, but there were materials we needed for the ritual... I delayed to secure them, and that is what lead to my capture.\n\nI will return to the circle, but I would be indebted to you if you would finish what I could not. We need hearts from the bound fire elementals that the Twilight's Hammer enslave in the western portion of the encampment.\n\nThe elementals are without hope, but in this sacrifice they can extract their revenge.\n\nFind me at camp.", progress = "Did you recover the hearts?", completion = "Thank you, {name}. You are quite capable. I'm extremely grateful that you've chosen to aid us.", objectives = "Gather 5 Fleshburner Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27304] = { id = 27304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet With Avaros Dawnglaive", description = "Avaros Dawnglaive sends word from Orgrimmar -- he wishes to speak with you when you're in the city. I needn't remind you that Avaros is an honored member of our order and his requests should not be ignored.\n\nNext time you are in Orgrimmar, travel to The Barracks in the Valley of Honor and speak with him.", completion = "I've heard much of your contributions to the Horde, {name}.", objectives = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27305] = { id = 27305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Love and Family", description = "Inside the Scarlet Bastion is a painting of great personal value to Highlord Tirion Fordring. Search for a painting of our twin moons. Chip away at the paint until you uncover the master work, 'Of Love and Family.'\n\nMay the Light guide your actions, and please handle the painting with the utmost care.", progress = "The painting, {name}. Do you have the painting?", completion = "Master Fordring will be glad beyond measure to see this painting again.", objectives = "Find 'Of Love and Family.'", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27306] = { id = 27306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to Ogron", description = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast.", completion = "Ogron? Yeah, that me.\n\nShh. Keep voice down. Crocs hear you.", objectives = "Find Ogron to the southeast of Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27307] = { id = 27307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elements Cry Out", description = "Do you feel it, {class}?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest.  Thus far we have been unsuccessful and now turn to others that may aid us.  Speak with Erunak Stonespeaker in Stormwind and see how you might be able to aid us.", completion = "I'm glad you've come, {class}.  These are troublesome times and we could use all the help we can get.", objectives = "Speak with Erunak Stonespeaker in Stormwind.Do you feel it, {class}?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest. Thus far we have been unsuccessful and now turn to others that may aid us. Speak with Erunak Stonespeaker in Stormwind and see how you might be able to aid us.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27308] = { id = 27308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elements Cry Out", description = "Do you feel it, {class}?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest.  Thus far we have been unsuccessful and now turn to others that may aid us.  Speak with Earthmender Norsala in Orgrimmar and see what tasks she may have for you.", completion = "I'm glad you've come, {class}.  These are troublesome times and we could use all the help we can get.", objectives = "Speak to Earthmender Norsala in Orgrimmar.Do you feel it, {class}?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest. Thus far we have been unsuccessful and now turn to others that may aid us. Speak with Earthmender Norsala in Orgrimmar and see what tasks she may have for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27309] = { id = 27309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", objectives = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27310] = { id = 27310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Weapons For You!", description = "Alright, these cowards want to fight? Let's see how well they do without any weapons.\n\nI'm sure you must have a torch, or something. Burn their weapon racks.\n\nBurn them all!", completion = "Let's see them wage their war now!", objectives = "Burn 8 Grimtotem Weapon Racks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27311] = { id = 27311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Weapons For You!", description = "The Grimtotem want to fight? Let us see how well they do without their weapons.\n\nI'm sure you must have something that burns. Set their weapon racks ablaze, my {class} friend.\n\nLet nature take its course.", progress = "We shall have to burn more of their weapon racks than that if we are to put a dent in their ability to fight.", completion = "Let us see how well they fight without their weapons.", objectives = "Burn 8 Grimtotem Weapon Racks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27312] = { id = 27312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcloud Grimtotem", description = "There's no way around it. If you want to win a battle, you have to spill some blood. In this case... a lot of it.\n\nYou know what we have to do.", completion = "That put a dent in their numbers! Can't say that they didn't deserve it.", objectives = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27313] = { id = 27313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcloud Grimtotem", description = "There is no alternative: if you intend to win a battle, you must spill the enemy's blood. In this case, unfortunately, a lot of it.\n\nYou know what we have to do.", completion = "While the Earth Mother does not condone such violence, we had no choice. The Grimtotem have ignored Her teachings for too long and are reaping what they have sown.", objectives = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27314] = { id = 27314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Sentinel training 101: take out their leaders and your enemy's forces will soon fall apart. We're going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. Let's see if we can't take her measure.", completion = "She was tougher than I thought. We worked well together, but we're going to have to make sure not to underestimate the other Grimtotem chiefs.", objectives = "Slay Isha Gloomaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27315] = { id = 27315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Basic brave philosophy dictates that if you kill the leaders of your enemy's forces, they will soon fall into disarray. We are going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. We will test her and her axe, and she will be found wanting.", completion = "She was more formidable than her reputation suggested. Although we worked well together, we must make certain not to underestimate the other Grimtotem chiefs.", objectives = "Slay Isha Gloomaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27316] = { id = 27316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nPerhaps the sentinel will have some insight into its significance?", progress = "That's the fabled Rattle of Bones, {name}!", completion = "It's true then! What is it doing here, though? And if it's here, that must mean that the writ and the drums are also nearby!\n\nMaybe there's some link between it and the wind serpent that just appeared? I think that I've an idea what that creature is as well.", objectives = "Give the Rattle of Bones to the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27317] = { id = 27317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nSurely the brave will have some insight into its significance?", progress = "The fabled Rattle of Bones, {name}!", completion = "It is true then! What is it doing here, though? And if it is here, that must mean that the writ and the drums are also nearby!\n\nPerhaps there is some link between it and the wind serpent that just appeared? I think that I have an idea what that creature is as well.", objectives = "Give the Rattle of Bones to the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27318] = { id = 27318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman of immense power. Supposedly, he is a direct disciple of Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he's here and that he's been training their geomancers. We have to kill him, {class}.", completion = "That's two of them. Two more to go.\n\nI wonder what he meant about being \"chosen\"?", objectives = "Slay Elder Stormhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27319] = { id = 27319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman chief of immense power. He was taught by Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he is here and that he has been training their geomancers. We have to kill him, {class}.", completion = "That was not pleasant. I wonder what he meant by calling you, \"the Chosen\"?", objectives = "Slay Elder Stormhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27320] = { id = 27320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writ of History", description = "In shu'halo myth, the Rattle of Bones is connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts.\n\nWe must keep our eyes peeled if we're to find the other two. The writ will most likely look like some kind of pictographic scroll if the stories are to be believed.", progress = "We'll need the actual writ, not just any tauren scroll hanging.", completion = "I'm fairly certain that's it. This is very intriguing, {name}. What are they doing here? Are they being used as a weapon?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?", objectives = "Collect the Writ of History.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27321] = { id = 27321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writ of History", description = "The Rattle of Bones is a part of shu'halo ancient myth. It is always connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts; gifts from the Earth Mother if the tales are to be believed. I cannot imagine Her being connected with the drums, though.\n\nWe must be vigilant if we are to find the other two. The writ will look like a pictographic scroll if memory serves.", progress = "We will need the actual writ, and not just any scroll hanging.", completion = "This is very exciting and also worrisome, {name}. What are these artifacts doing here? Are they being used as a weapons against us by the Grimtotem?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?", objectives = "Collect the Writ of History.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27322] = { id = 27322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korok the Colossus", description = "The monstrosity has fallen, granting a brief reprieve to the Forsaken soldiers on the front lines.\n\nTake Korok's second head and return it to Forward Commander Onslaught at Forsaken Forward Command.", progress = "Korok is dead?", completion = "That towering behemoth has killed hundreds of Forsaken soldiers. You've done a great thing, {name}.", objectives = "Take Korok's Second Head to Forward Commander Onslaught at Forsaken Forward Command in the Ruins of Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27323] = { id = 27323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the infamous Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe should take this opportunity to make sure that he doesn't go anywhere else.", progress = "We need to find and slay Grundig Darkcloud, {name}.", completion = "<The sentinel gives you an appraising look.>\n\nWhat is it with you? Why do they all seem spooked by you being here?", objectives = "Slay Grundig Darkcloud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27324] = { id = 27324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the most accomplished Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe must make the most of this chance and put an end to his campaign of terror once and for all.", completion = "<The brave gives you an appraising look.>\n\nThere is something special about you, {name}. That much is certain.", objectives = "Slay Grundig Darkcloud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27325] = { id = 27325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drums of War", description = "Whatever the Grimtotem are doing with these Drums of War, we don't want them to have them.\n\nDon't worry, {name}, we'll figure it all out. But first, we need to gather all of the pieces of the puzzle.", progress = "The tauren love their drums. I can only imagine the Drums of War will be somehow different from the others.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, {name}. Great danger lies ahead if Magatha Grimtotem has taken notice of you.", objectives = "Collect the Drums of War.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27326] = { id = 27326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drums of War", description = "Whatever it is that the Grimtotem are doing with the Drums of War, we do not want them to keep them.\n\nDo not worry, {name}, we will figure out what is going on here. But first, we need to gather all of the artifacts.", progress = "War is not an activity to engage in for those who are faithful to the Earth Mother's teachings.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, {name}. Great danger lies ahead if Magatha Grimtotem has taken notice of you.", objectives = "Collect the Drums of War.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27327] = { id = 27327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: The Chief of Chiefs", description = "And now the time has come to take out the leader of all of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nIt is said that he's the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. Supposedly, his indiscretions have left him in a state of disfavor with her.\n\nBut none of that matters right now. All that matters is that we kill him. For good this time.", progress = "We have to kill Arnak, {name}, if we are to win the battle for the tauren of Freewind Post.", completion = "For some reason they all think that you've been sent by Magatha Grimtotem. I know it must have something to do with that wind serpent that's been hanging around.\n\nDoesn't matter. Their leader is dead. It's only a matter of time before the tauren of Freewind Post regain their home.\n\nIf I were them, I'd push back a little to teach the Grimtotem a lesson, but they probably won't. They're tauren.", objectives = "Slay Arnak Grimtotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27328] = { id = 27328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: The Chief of Chiefs", description = "The time has come to deal with the leader of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nHe is the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. His indiscretions have left him in a state of disfavor with her.\n\nNone of that matters now. All that matters is that we deal with him. Once and for all.", progress = "Arnak must fall, {name}, if we are to win the battle against the Grimtotem.", completion = "They all believed that you have been sent by Magatha Grimtotem. There is no arguing that her pet, Arikara, has been lurking about.\n\n<The brave gives you a long look.>\n\nIt does not matter. Arnak is dead. It is only a matter of time before we take back Freewind Post.\n\nPerhaps now we will be able to establish a lasting peace with the Grimtotem?", objectives = "Slay Arnak Grimtotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27329] = { id = 27329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands.", objectives = "Defeat Arikara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27330] = { id = 27330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands.", objectives = "Defeat Arikara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27331] = { id = 27331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "Thank you for coming to see me, {name}.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27332] = { id = 27332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "The spirits knew that you would answer my call, {name}.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27333] = { id = 27333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "I don't know how much longer we can hold out for, {name}. Crowley and Bloodfang's worgen know every hidey hole and safe spot in Gilneas. One minute they're standing in front of you and the next minute they're gone! We're gonna lose this war to attacks of opportunity, even though we have a superior military presence.\n\nBut momma didn't raise no quitter! Forsaken until the end, my friend.\n\nHead west into the headlands and help our soldiers on the front line. Kill the attacking worgen rebels!", progress = "Kill the rebels!", completion = "If I could still breathe I'd let out a sigh of relief.\n\nDon't get too comfortable, though, {name}, your mission here has just begun.", objectives = "Kill 12 Worgen Rebels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27334] = { id = 27334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "There you are, {name}. I was beginning to think my message hadn't found you.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27335] = { id = 27335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "Welcome, {name}. I'm glad that you accepted my invitation. We have much to discuss.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27336] = { id = 27336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility.", objectives = "Use the Captured Totem to set it on the ground, and kill 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws near it to test its effects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27337] = { id = 27337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Weapon", description = "From your earliest days, {name}, your trainers identified you as a natural talent. Your rapid progress and dedication have made you an example.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nLegend has it that the cursed Shadowfang Keep in Silverpine Forest is home to a variety of materials that you will need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ander told me to expect you. It's quite an honor to be crafting a weapon for you, {name}. With these materials, it will be a fine blade indeed.", objectives = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27338] = { id = 27338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Boys on the Shore", description = "The situation here in the Highlands changes by the minute. Our objective is to storm the Bastion of Twilight, but I can't even secure a landing zone on the shore without the blasted Horde creating trouble.\n\nWhile I scrape together the remains of the fleet, I need men on the shore securing the beach head.\n\nReport to Lieutenant Emry on the shore and help his marines to beat back the Horde!", completion = "Keep your head down 'fore you lose it, {class}!\n\nThis is MY beach.\n\nThe Horde WANTS my beach.\n\nThey will NOT have my beach.\n\nIs the beach situation clear?", objectives = "Report to Lieutenant Emry at the Twilight Shores in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27339] = { id = 27339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference.", objectives = "Collect 6 vials of Marsh Venom from Darkfang Creepers or Noxious Shredders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27340] = { id = 27340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", progress = "Have you made any progress in stopping the Grimtotem attacks?", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?", objectives = "Kill 12 Grimtotem in Direhorn Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27341] = { id = 27341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Shore", description = "It's them or us, {class}. Only one of us can command this beach.\n\nNorth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand up and down the shore!\n\nI need to know what the current situation is. Scout the beach head control point, marked by that enormous flag, and return to me.\n\nYou don't have to try to capture it, unless you're spoiling for a fight...", completion = "That's the lay of the land, soldier. If you're having trouble fighting here on the coast, you might consider pitching in and helping us take and hold that hill.", objectives = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27342] = { id = 27342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Time, All Will Be Revealed", description = "The Dark Lady has sent you and Arthura here for a very specific purpose. Before I tell you more, we must make preparations.\n\nHead east into the forest of Gilneas and search near the trees and rocks of the region for a special plant known as wolfsbane. Gather as much of the wolfsbane as you can carry and return to me.\n\nOur mission here goes far beyond the scope of the battlefield, {name}. In time, all will be revealed.", progress = "Did you gather the wolfsbane?", completion = "<Belmont takes the wolfsbane from you.>\n\nGood. Now just do as Forward Commander Onslaught commands. Try your best to fit in with the rest of the soldiers. We don't want the Gilneas Liberation Front to get suspicious.\n\nOh, you didn't know they were watching us? Right now there are five different worgen spies looking down on our position. Just be calm and follow orders. I'll let you know when we are ready to proceed.", objectives = "Collect 6 Wolfsbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27343] = { id = 27343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of the Light", description = "I have been watching your progress, {name}, and I can only conclude that the Light shines brightly upon you. You are becoming an exemplary {class}.\n\nTo honor your dedication, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials to make your weapon are unique, and only found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", progress = "Do you have the materials for your weapon?", completion = "Lord Grayson has told me much about you and your dedication to the Light and the Alliance. It will be a great honor to craft a hammer for you, {name}.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27344] = { id = 27344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Well-Earned Reward", description = "I am not the only one impressed by your progress {name}. Your mastery of bow and pet and your dedication to the Alliance have reached the ears of King Wrynn.\n\nIn recognition of your service, the king has commissioned the royal bowyer to craft a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the unique materials needed for your weapon. Travel there and obtain the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Who knew that cursed old keep hid such valuable items? I'll be honored to craft them into a fine weapon for you.", objectives = "Go to Shadowfang Keep and obtain the Godfrey's Crystal Scope from Lord Godfrey, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27345] = { id = 27345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The F.C.D.", description = "Communications are down with all of our frontline outposts, {name}. As of right now I don't have a damn clue as to the status of our troops in Gilneas. We need to re-establish communications.\n\nI need you to head west into the headlands and find our outpost on the coast. By now the soldiers there are likely all dead, but their F.C.D. might be operational. Grab the device and get back to me.", progress = "Recover the F.C.D.", completion = "With this device I will be able to communicate with you in the field. Now to check the rest of our frontline outposts.", objectives = "Recover the Forsaken Communication Device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27346] = { id = 27346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and its pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway.", objectives = "Speak with Moxie Steelgrille at Beezil's Wreck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27347] = { id = 27347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, {class}! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage.", objectives = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27348] = { id = 27348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now.", objectives = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27349] = { id = 27349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break in Communications: Dreadwatch Outpost", description = "I'm not gonna lie to you, {name}. What I'm about to ask you to do is suicide. Chance of failure is about 95%.\n\nAll communication from Dreadwatch Outpost has been severed. With the worgen constantly rushing us we have no means by which to get to Dreadwatch to check on our soldiers. I need you to head south to the outpost and check on our soldiers. I'll keep in contact through the Forsaken communication device - F.C.D. - from here on out.\n\nKEEP CLEAR OF THE MAIN ROAD.", completion = "<The F.C.D. crackles with static.>\n\nDreadwatch is lost? This is bad, {name}. Real bad.\n\nIf Dreadwatch is compromised it means we've lost Gilneas City.", objectives = "Investigate Dreadwatch Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27350] = { id = 27350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break in Communications: Rutsak's Guard", description = "<The F.C.D. hums.>\n\nOur next outpost is Rutsak's Guard, located due east of Dreadwatch. Make your way to Rutsak's while avoiding the worgen rushers, {name}. You don't want to deal with those monsters by yourself.\n\nIf you make it there in one piece, look for Captain Rutsak.\n\nJust be prepared for the worst.", completion = "Th... Af... After we lost Gilneas City, the port fell.\n\nHU... HUM... HUMANS ARE HERE! Reinforcements from Stormwind! They slaughtered my men. Left me alive to witness their strength. To tell high command... To tell them that the 7th Legion are here...", objectives = "Find Captain Rutsak at Rutsak's Guard in the Ruins of Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27351] = { id = 27351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Reward", description = "SI:7 has been watching your progress with interest. You service to the Alliance is well-known and tales of your deeds have reached the king's ears.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the exotic materials for your weapon. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "It was quite an honor to receive the commission for your weapon, {name}. When Tony mentioned using so many exotic materials, I had my doubts, but it seems you managed to find them all. This will be a fine reward for all you've done for the Alliance.", objectives = "Go to Shadowfang Keep and obtain the Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27352] = { id = 27352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Gold", description = "As the Scourge swept through Stratholme like a plague, the Knights of the Silver Hand manufactured holy water to use against the invaders. They stored it inside small crates along with other vital supplies, and distributed them throughout the city. Unfortunately, the citizens turned into Scourge reinforcements before the supplies could ever be used!\n\nThese supply crates will prove extremely useful to our efforts. Bring me a vial of Stratholme Holy Water, we need to have it replicated in mass quantities.", progress = "Is that the vial of Stratholme Holy Water?\n\nWait, is that just regular water? Don't play games with ol' Stonebruiser!", completion = "Excellent! I think the holy water will prove devastating in large volumes.", objectives = "Find a vial of Stratholme Holy Water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27353] = { id = 27353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of the Elements", description = "Your talent has attracted much attention in shamanic circles, {name}. Word of your mastery of the elements and dedication to the Alliance has even reached the palace.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials for your weapon can only be found in Silverpine Forest's cursed Shadowfang Keep. Travel there and retrieve Lord Walden's talisman, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I have rarely had the chance to work with such exotic materials, but even I can sense the power residing within them. I will have the honor of crafting an incredible weapon for you, {name}. The farseer did not underestimate your abilities when she told me about you.", objectives = "Go to Shadowfang Keep and obtain Walden's Talisman, the Book of Lost Souls, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27354] = { id = 27354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "You have proven yourself a brilliant student and a dedicated servant of the Alliance. Word of your accomplishments has even reached the ears of the king.\n\nIn recognition of your service, King Wrynn has commissioned the royal enchanter to create a special weapon.\n\nThe materials required for your staff are found only in Silverpine Forest's cursed Shadowfang Keep. Travel there and find a lost heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, I have been expecting you, {name}. Maginor Dumas has spoken highly of you and the royal commission only confirms his words. It is an honor to be able to craft a staff for you.", objectives = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27355] = { id = 27355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boon for the Powerful", description = "The king is finally beginning to take note of our power and our value to the Alliance, thanks to your deeds. Perhaps they are beginning to accept our kind.\n\nKing Wrynn has commissioned the royal enchanter to create a powerful weapon in recognition of your achievements.\n\nThe materials you will need come from Silverpine Forest's Shadowfang Keep. Travel there and obtain the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I won't ask what you had to do to come by such rare and powerful materials, but I'm glad to have the chance to work with them. Your weapon will be magnificent!", objectives = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27356] = { id = 27356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the {class} Loganaar was talking about. It is a pleasure to finally meet you. Loganaar and other members of the circle speak highly of you. It will be an honor to make a weapon for such a {class}.", objectives = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27357] = { id = 27357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Bride", description = "Of course! Lakota Windsong! Why didn't I think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, {race}?", objectives = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27358] = { id = 27358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Bride", description = "Lakota Windsong! Why did I not think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, {class}?", objectives = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27359] = { id = 27359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Reinforcements", description = "The Scourge have some sort of ward in place that's preventing me from opening a portal so that our reinforcements can help us take the city! It's like a neverending screaming inside of my head! Agh!\n\nI'm doing all I can to retain my sanity from that noise with this barrier. My best guess is that the banshees are maintaining the defense. If you could bring me some of their essences, I think I can use them to counteract the ward and get our boys in here!", progress = "Were you able to obtain the essences? Be careful, they're deadly spellcasters.", completion = "Oh my... the banshees are very tortured souls indeed. Merely holding their essence is emotionally painful...\n\nEnough of that for now. I'll get to work on counteracting their magic, then we'll have a portal up and running in no time. Stratholme will be ours soon, I just know it.", objectives = "Obtain 4 Banshee Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27360] = { id = 27360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Our Soldiers", description = "7th Legion... They rushed us in the dead of the night. Their captain barked orders as the submariners slaughtered my men. Then he came to me, put his face in mine, and said something I'll never forget:\n\n\"The name's Master Sergeant Pietro Zaren, officer in the 7th Legion. When you see your soldiers being slaughtered in your nightmares - if you even still dream - remember my name and tremble.\"\n\nAvenge my soldiers! Kill the 7th Legion occupying the Cathedral Quarter of Gilneas City, southwest of here.", completion = "Though we were shamed in battle, the enemy was not victorious. I will not soon forget this, {name}.\n\nIf I make it back to Silverpine I will likely retire from the service. War is not in my blood.", objectives = "Kill 10 7th Legion Submariners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27361] = { id = 27361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of the Light", description = "The Light truly shines in you and your dedication to the Alliance, {name}. You serve as an example to your fellow priests and comrades in arms.\n\nIn recognition of your deeds, King Wrynn has commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27362] = { id = 27362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of Elune", description = "You are a true servant of Elune, an example to our people, and stalwart servant of the Alliance. The Temple of the Moon and the court of Stormwind wish to honor your achievements.\n\nWe have commissioned the royal enchanter to create a staff for you.\n\nThe materials for your staff can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27363] = { id = 27363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Budding Young Surgeon", description = "You have shown yourself to be a capable priest and a credit to the people of Gnomeregan. The high tinker and the king of Stormwind wish to honor your contribution to the Alliance.\n\nThey have commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27364] = { id = 27364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Whose Orders?", description = "<The F.C.D. buzzes.>\n\nThe 7th Legion are an elite special ops regiment. They've been there, behind the scenes, for almost every major offensive and military engagement the Alliance has ever done. This is bad news. How did they get past our warships? And on whose orders are they here?\n\nWe need to get our hands on their orders. This Pietro character will undoubtedly have vital information. Find him at the Cathedral Quarter in Gilneas City and take him out. Search his corpse for clues.", progress = "Status?", completion = "<The F.C.D. crackles with electricity.>\n\nAn Alliance armada is en route? How could this have happened?\n\n<Forward Commander Onslaught cuts out for a moment. You hear worgen howling in the background.>\n\nYou've got to hurry, {name}. We're being overrun up here at Forward Command.", objectives = "Recover the Orders from High Command.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27365] = { id = 27365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Weapon", description = "From your earliest days, your trainers always knew you would make your mark on the Horde. You have fought bravely and given our enemies reason to fear.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Grezz Ragefist told me to expect you. Those materials will make a fine sword. Always use it for the glory of the Horde.", objectives = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27366] = { id = 27366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landgrab", description = "The Horde's Axebite Marines are all up in my precious, precious beach.\n\n<The Lieutenant points north, along the shore.>\n\nKill them.", completion = "Dead? By the dozen?\n\nIt's a start, {class}. It's a start.", objectives = "Slay 12 Axebite Marines on the Twilight Shores in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27367] = { id = 27367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldbraids", description = "I love my boys, don't get me wrong.  But I TOLD them that I needed FIVE MINUTES to water and brush the horses, and what did they do?  They made a stupid bet with each other and ran off!  I should have known better... this always happens.\n\nGidwin's the short one.  He headed north, along the river.  If you're headed that direction, would you tell him to come back?  We've got to get to Light's Hope Chapel, and I'm not against leaving without him.", completion = "Tarenar?  Is that you?\n\nWhoever you are, would you mind helping me out of this thing?", objectives = "Find Gidwin Goldbraids in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27368] = { id = 27368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Encased", description = "You should have seen me fight!  I must have killed six of those beasts, when...\n\nOh wait, you can count the bodies, can't you?  OK, fine.  I killed four of them, when the fifth one shot me with this web.  To make things even worse... when he blasted me with web juice, my mouth was open!\n\nI can't seem to break these webs, and I doubt you'll be able to, either.  No, you'll have to get some of the stomach juice from those undead spider-things.  That'll do the trick.", progress = "Oh boy... Fiona is going to be madder than a wet harpy.  You'd better hurry.", completion = "You're back?!  Thank the Light!\n\nBefore you throw that acid on me, I need to ask: Are you the guy who was here before, or are you one of those eight-legged cowards?  I need to know whether or not I should smack you on my way out.", objectives = "Obtain 8 vials of Crypt Bile from nerubians in Terrorweb Tunnel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27369] = { id = 27369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greasing the Wheel", description = "Sorry about that.  I was pretty sure you were one of those spider-beasts, doing a bad {race} impression.\n\nHow do you do?  Gidwin Goldbraids, at your service.  I'm in a bit of a hurry back to my caravan, but I was wondering if you might do me one last favor?  My pal Fiona runs a small shop, and she could probably use some of these herbs that grow along the river shore.\n\nI'm thinking if we give her some nice herbs, she'll be MUCH less likely to murder me.  That's the plan, anyway.", progress = "Giddy's got you mixed up in all of this now?", completion = "I'll tear that pint-size paladin to shreds before he... wait a minute are those Banshee's Bells?  You brought these for me?\n\nOh, Gidwin asked you to get them for me!  That sweet little guy.  Alright.  He's off the hook for now.", objectives = "Loot 10 Banshee's Bells from the shore of the Thondroril River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27370] = { id = 27370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sunstrike", description = "As soon as we stopped, they made a bet about \"who could kill the most undead in five minutes.\"\n\nIt's been an hour, and I'm still waiting for them to come back.\n\nI saw Tarenar run off to the southeast.  Unfortunately, I can't leave the caravan here by itself.  If you end up traveling in that direction, could you find him and send him back to me?", completion = "I've found them, {race}.  The Scourge.  How I've longed for this day.", objectives = "Find Tarenar Sunstrike at Death's Step in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27371] = { id = 27371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What I Do Best", description = "I remember when I was young, I would sneak off into the Ghostlands and just beat up zombies for hours on end.  Nobody even PAID me.  I just did it.\n\nNow, look in front of you.  Those are some serious zombies.  I was just about to start beating them up, too.  Care to join me?", completion = "Five should be good enough.\n\nYikes, look at the time!  I need to head back to camp.", objectives = "Kill 5 Death's Step Miscreations at Death's Step in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27372] = { id = 27372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fiona", description = "My traveling companion, Fiona, runs a small vendor's shop out of her caravan.  She and I, along with our friend Gidwin, are all on our way to Light's Hope Chapel.  I'm sure you can join us, if you like... though Fiona might be a little mad at me.\n\nFiona always forgets why she's mad if you give her a gift.  Kill some of the plaguehounds north of here, then bring their blood to Fiona at the caravan, down by the river.  She'll love it.  We'll talk again there.", progress = "I should have guessed it.  Tarenar made you get me a gift?  That thoughtless idiot!\n\nUmm... what was the gift, anyhow?", completion = "Why, this is exactly what I needed!  Fine, I'll forgive Tarenar for running off.\n\n{name}, you're welcome to join us anytime.", objectives = "Obtain 10 samples of Plaguehound Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27373] = { id = 27373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward, to Light's Hope Chapel", description = "Now that the boys are back, we can head out.  You headed east?\n\nPlease, join us!  I insist!  Yesterday, we were in the Menders' Stead, and I was telling Tarenar, \"We have two paladins and a shopkeeper, but you know what we really need?  A {class}!\"\n\nDon't look at me that way!  I'm serious!  Come on, hop in the cart.", completion = "Hope the ride wasn't too bumpy for you.\n\nHave a look around the tower while the horses rest.  It's no Light's Hope Chapel, but I'm sure you can find some way to keep yourself busy.", objectives = "Board Fiona's Caravan at the Thondroril River in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27374] = { id = 27374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw of Madness", description = "I can't believe it, {name}. Me own son - me own flesh and blood! Throwing his lot in with those fiends from the Twilight's Hammer. Did you see what he became when he tried to destroy the wedding? Oh ... why? Why?\n\nIt's that beast, {name}. The enormous mouth emerging from the earth to our west. \"The Maw of Madness!\" My son said it spoke to him, but I thought it was just nightmares.\n\nThe Earthen Ring is trying to destroy it. Go to Earthcaller Torunscar, west of here, and see how you can help!", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help.", objectives = "Speak to Earthcaller Torunscar at the Ring of the Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27375] = { id = 27375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weeping Wound", description = "A beast, {name}! I saw a beast. A great maw, an even greater hungering. They can't possibly know what they unleashed.\n\nIt is here. Its terrible shapeless body is erupting right into the Highlands.\n\nI saw you in my vision, {name}. You struggle with the Earthen Ring to contain the beast. You will face the darkness.\n\nGo now, before the beast grows in power. Speak to Earthcaller Torunscar at the Circle of the Elements, northwest of here atop the ridge beyond the ruined Drakgor Encampment. Hurry!", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help.", objectives = "Speak with Earthcaller Torunscar at the Ring of the Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27376] = { id = 27376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw of Iso'rath", description = "We are ready to attack the beast. First, we need to destroy it's tentacles, then Yevaa will perform a ritual to summon a powerful fire elemental that we will drop into its maw.\n\nI want you to fly out with our first group attack. Hold steady until an opportunity presents itself, then join the battle with the rest of the shaman in cutting the tentacles down.\n\nTake any one of the gryphons when you're ready to join the assault.", completion = "The tentacles swept us off of our gryphons as well! They were far more nimble than we anticipated.\n\nNo matter. We were prepared for this possibility. I can summon the elemental from here if you can keep me safe.", objectives = "Mount a gryphon to join the attack on Iso'rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27377] = { id = 27377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devoured", description = "We knew this was a possibility, but we had no idea how the beast would defend itself. Iso'rath's body is reacting quickly to our threat.\n\nI can complete the summoning from here, but only if you can hold back Iso'rath's defenses. Keep them busy! We will survive this!", completion = "I've brought you back from the brink of death, hero!\n\nDeathwing is upon us! We need your help.", objectives = "Defend yourself and Earthcaller Yevaa from Iso'rath's bodily defenses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27378] = { id = 27378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Worldbreaker", description = "There's no time! Deathwing struck before we could form against him. If you do not stop him, the Earthen Ring will end this day!", completion = "You're awake! Thank the elements. I'd almost lost all hope.", objectives = "Defeat Deathwing, the Aspect of Death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27379] = { id = 27379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrors of Iso'rath", description = "We need you! You were stuck in some kind of nightmare. So are many of the other shaman.\n\nIt doesn't matter... our plan is falling apart. Some of our shaman are channeling protective auras that should combat the digestive juices and keep you alive, but we need you to rescue the other shaman from the tentacles.  We won't be able to defeat Iso'rath without them!\n\nDon't stay out in the stomach without the other shaman for too long or you'll be digested alive!", progress = "The battle is not over. The shaman within Iso'rath need you!", completion = "United with the Earthen Ring, we can survive the horrors of Iso'rath. Now it is time to turn our vengeance upon him!", objectives = "Rescue Hargoth Dimblaze, Earthmender Duarn, Stormcaller Jalara, and Stormcaller Mylra.\n\nReturn to the safety of the other shaman if Iso'rath's defenses are eating away at you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27380] = { id = 27380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare", description = "Iso'rath's brain is revealed! The shaman you've saved should keep you somewhat safe amidst his defenses.\n\nStrike at the brain and destroy Iso'rath!", completion = "You saved many of my closest allies today, {name}. I can only imagine what horrors you witnessed within Iso'rath, but you have the thanks of all of the Earthen Ring.", objectives = "Destroy the Brain of Iso'rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27381] = { id = 27381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling Companions", description = "While we're waiting here at this tower, we might as well see if anybody else is headed to Light's Hope Chapel.  The more, the merrier, I say!\n\nAsk around to see if anybody wants to join us on our trip.  I'm sure you can find somebody who's headed to Light's Hope.", progress = "Any luck?", completion = "Argus Highbeacon... that old guy on the top of the tower?  Great!\n\nA man his age must have been in the Argent Crusade for a long time.  Maybe he can put in the good word for us at Light's Hope.", objectives = "Find someone at Crown Guard Tower who will join your caravan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27382] = { id = 27382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rough Roads", description = "The Argent Crusade built these towers to be points of light in the darkness of the Plaguelands.  I walk the paths between these towers, protecting and maintaining them.\n\nThe roads have been dangerous lately.  Plagued wildlife runs rampant, and bats swoop down upon unsuspecting travelers.  It would make the next leg of my journey much easier if you could clear some of this wildlife out of the way for me.", completion = "Of course a young {race} like you would have no trouble taking care of a few wild animals.  With the roads clear, my journey to the next tower will be much easier.", objectives = "Slay 13 Plaguebats along the path to Light's Shield Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27383] = { id = 27383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Pamela", description = "The battle for Darrowshire still haunts me, {race}.  I wake up in cold sweats, convinced that I'm still there; that it is happening all over again.\n\nI've coped with the loss of my comrades, but the loss of my family members is still cripplingly painful.  One of my kin lost during the attack was my young niece, Pamela.\n\nIf you are brave enough to enter Darrowshire, will you search for any sign of Pammy?  Darrowshire's ruins are due south of here.", completion = "Hello.  I'm Pamela, what's your name?", objectives = "Find Pamela Redpath in Darrowshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27384] = { id = 27384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamela's Doll", description = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!\n\nBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!\n\nAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.\n\nWill you find my doll for me?", progress = "Did you find my doll?", completion = "You found it!  You found my doll!  Oh, thank you!", objectives = "Find Pamela's doll.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27385] = { id = 27385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncle Carlin", description = "I'm going to play with dolly, but I don't want to play with daddy's sword after all.  You'd better keep it.\n\nEven better, can you give it to my uncle Carlin?  I'm not sure where he is, but sometimes I hear him crying.  It sounds like he's nearby, to the north.\n\nI hope he's not crying for me!  {name}, will you find my uncle and tell him I'm alright?\n\nIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!", progress = "Any news of my Pammy?", completion = "You've seen Pamela?  She's alive?\n\nShe's dead?  No!  Oh, Pamela!  Why does your spirit still suffer in this world?  Why are you perished, while fortune keeps me alive?  In an instant I would switch places with you and wander dead Darrowshire, a ghost and alone!\n\nAh, but this news cannot change fate.  Thank you, {name}.  Now my duty, my duty to revenge, burns hot as ever.\n\nSay, what is that sword you have there?", objectives = "Return to Carlin Redpath at Crown Guard Tower in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27386] = { id = 27386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Historian", description = "That sword belonged to Joseph Redpath, Pamela's father - though you probably already knew that.  I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.\n\nPamela's fate is sealed, but perhaps we can change Joseph's fate.\n\nA strange gnome arrived here at this tower not long ago.  Her name is Chromie.  Take that sword to her.  I have a feeling she will be able to help us.", progress = "There is something timely about your visit.  You're not from the future, are you?", completion = "What is this?  A warsword?  A butter knife?  I'm useless when it comes to blades.  Let me see...\n\nAh!  This sword was once in the hand of a great man, but there is much tragedy in that man's past.\n\nAre you here to help him?  It's far too late for him now... but perhaps we can help him in the past!", objectives = "Bring Joseph's Hunting Blade to Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27387] = { id = 27387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Villains of Darrowshire", description = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  He was slain among the foothills north of here, and his skull remains there.\n\nMarduk the Black was never defeated, but his fabled sword now rusts, ownerless.  It can be found near the road to our southeast.\n\nRetrieve these items, {name}.  I know not why, but I am certain their fate lies with you.", progress = "Did you find the skull and the sword, {name}?", completion = "You found them!  Well done, {name}!  These relics hold within them the memories of the Scourge forces at Darrowshire.  We will need these if we are to save your Joseph Redpath.", objectives = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Chromie at Crown Guard Tower in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27388] = { id = 27388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of Darrowshire", description = "The heroes of Darrowshire held relics of their own, and inside of those relics lie more precious memories.\n\nFirst, speak with Carlin and obtain the Extended Annals of Darrowshire.  Within the tome lies the narrative that will drive our excursion through time.\n\nThen, you will need to head west to the Marris Stead.  The former owner of the Marris farmhouse collected relics from the battle of Darrowshire - for what reason, I am not certain.\n\nGather these relics, and return to me.", progress = "Do you have the relics, {name}?", completion = "You have the relics?  Good.  I will get to work on resolving any temporal discontinuities.\n\nDon't worry... that's not something you have to worry about.  You just gather the reagents.", objectives = "Obtain the Extended Annals of Darrowshire from Carlin Redpath, and obtain Davil's Libram and Redpath's Shield from the Marris Stead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27389] = { id = 27389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauders of Darrowshire", description = "I require a rare reagent for the powerful spell I intend to cast: skulls from the scourge who took part in the battle of Darrowshire.\n\nTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.\n\nGo, {name}.  You'll find scourge champions in the Fungal Vale to the north.  Go.", progress = "Do you have the skulls?  They are critical for my spell, which will give us the chance to save Darrowshire.  Maybe.", completion = "Excellent work, {name}.  Are you certain you haven't done this before?", objectives = "Bring 5 Resonating Skulls to Chromie at Crown Guard Tower in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27390] = { id = 27390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Darrowshire", description = "Now, {name}, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", progress = "I think I heard ghosts outside.  They whisper scary things to me...", completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if came to our house, so I made some tea!\n\nI hope you like lots of sugar!", objectives = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27391] = { id = 27391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Treasures", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you {name}.  Thank you!  You're a very nice <man/lady>!", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens...", objectives = "Bring Joseph's Key to Joseph's Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27392] = { id = 27392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Supposed to Tell You This", description = "My daddy always kept two swords: one for fighting with men, and one for hunting the animals.  I wasn't supposed to touch his swords, but I knew where he hid them.\n\nOne day, he told my mommy that he was going to fight a \"lone hunter\" in the hills to the east, but he brought his animal sword with him!  When he came back, he didn't have his sword with him.\n\nWhen daddy comes back, he'll be so happy when I give him his animal sword!  Will you go and find it?", progress = "Daddy loved his animal sword.  He seemed sad when he didn't have it anymore.", completion = "That's my daddy's sword!  How did you find it?  Did you find the bad hunter?", objectives = "Obtain Joseph's Hunting Blade from The Lone Hunter in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27393] = { id = 27393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", completion = "The Wavespeaker was right. There's something here.", objectives = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27394] = { id = 27394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", completion = "The Wavespeaker was right. There's something here.", objectives = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27395] = { id = 27395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marksman's Weapon", description = "You have picked up the ways of the hunter quickly, {name}. Your skills have made you a credit to the Horde and an example to the younglings.\n\nAs a reward for your progress and hard work, the warchief has commissioned his personal bowyer to create a unique weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials we'll need. Travel there and retrieve the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I'm honored that the warchief chose me to craft a weapon for you, {name}. With such exotic materials, it will be a very fine bow.", objectives = "Go to Shadowfang Keep and obtain Godfrey's Crystal Scope, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27396] = { id = 27396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade of the Shattered Hand", description = "Many members of the Shattered Hand do not survive their training, {name}. Not only have you survived, but you will soon become a feared blade of the Horde.\n\nAs a reward for your progress, the warchief has commissioned his personal smith to forge a weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Gordul told me that you would be bringing a variety of unusual materials, but I didn't expect anything like this. Moonsteel is said to be very rare and there's only one place I know to get it. You have risked much for this weapon, {name}, and I'll see to it that you receive a fitting reward.", objectives = "Go to Shadowfang Keep and obtain Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27397] = { id = 27397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hretar's Task", description = "The elements and spirits speak to you with clear voices, {name}. You have become a powerful shaman and an example to others wishing to serve the Horde.\n\nWord has even reached the warchief, and he has commissioned his personal smith to forge a special weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and obtain Lord Walden's talisman, the Book of Lost Souls, and essence from the ghosts haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be {name}. Kardris said that you were venturing to Shadowfang Keep to find the materials needed for this weapon and I see that you have not disappointed. I will make you a mighty weapon worthy of what you have brought.", objectives = "Go to Shadowfang Keep and obtain Walden's Talisman from Lord Walden, the Book of Lost Souls, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27398] = { id = 27398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City for further instructions.", completion = "Your aid is most timely, {name}.", objectives = "Speak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27399] = { id = 27399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", completion = "Your aid is most timely, {name}.", objectives = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27400] = { id = 27400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "All of your trainers agree, {name}, you show an amazing amount of talent for a journeyman. Even the warchief has heard of your rapid progress.\n\nAs a reward for mastering your studies, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find a magical heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be the {class} that Uthel'nay mentioned. I've heard tales about the artifacts the Silverlaine family once kept, but I haven't ever seen one. This should make an excellent focus for your staff. Let's get started.", objectives = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27401] = { id = 27401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Tomorrow Brings", description = "<The F.C.D. buzzes.>\n\nLook around the Cathedral Quarter. There should be a telescope nearby that the 7th Legion uses for spying. Find it and use it to scout the harbor. We need to find out how the 7th Legion got past our fleet.\n\nHurry, {name}. We can't hold these beasts back much longer.\n\nWhat does tomorrow bring?", completion = "<The F.C.D. crackles with electricity.>\n\nTORPEDOED! We had everything at the water line covered, but nothing below the line. They must have snuck in beneath our defenses and then blown our warships to smithereens.\n\nAnd now the rest of the Alliance fleet is nearly here...", objectives = "Use the 7th Legion Telescope to Scout the Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27402] = { id = 27402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Token of Power", description = "Your mastery of our ways continues to grow quickly, {name}, and I am far from the only one impressed by your progress. Even the warchief has taken note of your deeds.\n\nAs a reward for your dedication, the warchief has commissioned his personal enchanter to craft a staff.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and retrieve the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "So you are the {class} who will receive this staff. It will be a fitting reward for one so dedicated to the pursuit of power and the ascendancy of the Horde.", objectives = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27403] = { id = 27403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Sunwalker", description = "I have watched your training, {name}. Yours is the path of an exemplary Sunwalker, a brave defender of the Horde and a follower of our ways.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I haven't worked with the Sunwalkers before, but from all I've heard, the warchief holds you in high regard. It was a great honor to be asked to forge this weapon for you and I hope it will serve you well.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27404] = { id = 27404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the {class} Loganaar was talking about. It is a pleasure to finally meet you, {name}. I've often heard members of the circle describe you as a talented and promising {class} and I'm heartened to see their estimations were correct.", objectives = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27405] = { id = 27405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall Back!", description = "<The F.C.D. buzzes.>\n\n<Howls can be heard in the background.>\n\n{name}, do you read me? Come in, {name}. This is likely my final transmission. The worgen have overrun Forsaken Forward Command. It is now only a matter of time before the base is lost. Belmont and the val'kyr, Arthura, have left. Belmont mentioned that they will rendezvous with you at Emberstone Village, located to the northeast. Find Belmont, {name}. Our mission - our very existence - depends on it.\n\nYou are our final hope.", completion = "Forward Commander Onslaught fought until the bitter end, {name}. It took a pack of bloodthirsty worgen to finally bring him down. We must not let his death, or the death of all of our soldiers in Gilneas, go in vain. Our mission MUST succeed.\n\nNow I will reveal to you why we are here.", objectives = "Find Deathstalker Commander Belmont at Emberstone Village in the Ruins of Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27406] = { id = 27406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Man Named Godfrey", description = "Lord Vincent Godfrey spent his life defending the kingdom of Gilneas. When the worgen curse ravaged this land, Godfrey was one of the first Gilneans to take up arms against the beasts. It is said that upon discovering that his king was afflicted by the curse, Godfrey took his own life. He would rather be dead than serve the very creatures that he had defended his home against.\n\nWe are going to give him a second chance, {name}. Together we will battle southeast towards Tempest's Reach to collect his corpse.", progress = "Lord Vincent Godfrey. The name itself evokes feelings of dread in the hearts of worgen.", completion = "Here we are, {name}. He is a little rotted, but no worse for the wear. We must hurry before the Alliance finds us!", objectives = "Find the corpse of Lord Vincent Godfrey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27407] = { id = 27407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodfen Feathers", description = "Are you startled by Brogg's presence here, little {race}? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual.", objectives = "Collect 5 Bloodfen Feathers from Bloodfen Raptors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27408] = { id = 27408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, {name}.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, {name}. Brogg has big plans for clan banner.", objectives = "Retrieve the Stonemaul Banner from within the Den of Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27409] = { id = 27409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, {name}. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends.", objectives = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27410] = { id = 27410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do.", objectives = "Put 10 Stonemaul Spirits to rest at the Stonemaul Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27411] = { id = 27411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. {name}, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg know Onyxia dead. Brogg know her brood still there. Brogg not let them forget the Stonemaul.\n\nBrogg is grateful for your help, {name}, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong.", objectives = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair and defeat anyone who answers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27412] = { id = 27412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", progress = "You look pretty satisfied with yourself. Come to claim the bounty on that monstrous raptor?", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!", objectives = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27413] = { id = 27413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", objectives = "Collect 8 Wyrmtail stalks in the Dragonmurk or Wyrmbog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27414] = { id = 27414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, {name}? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home.", objectives = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27415] = { id = 27415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", progress = "You must hurry to the Dragonmurk, {name}. With Onyxia's eggs riddled around the Wyrmbog, we face overwhelming numbers unless something is done quickly.\n\nDestroy her eggs! Don't let the black dragon plague spread across our homeland!", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, {name}.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south.", objectives = "Destroy 5 Eggs of Onyxia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27416] = { id = 27416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here.", objectives = "Speak with Overlord Mok'Morokk in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27417] = { id = 27417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done.", objectives = "Speak with Draz'Zilb in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27418] = { id = 27418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny {race}!\n\nYou tell me when ready for good beating.", completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, {name}.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.", objectives = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27419] = { id = 27419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", objectives = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27420] = { id = 27420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postponing the Inevitable", description = "You have a keen eye to have seen me here, hidden among the grasses.\n\nAhead of us lies the Fungal Vale, an area that the Scourge still cling tightly to.  They use floating constructs to continually re-plague the land, keeping it vile and polluted.\n\nThe devices are controlled with runes, which are held by dark adepts and shadowmages.  Take the controlling runes that these cultists hold, aim them at the plague disseminators, then overcharge them with this mote.  The results should be amusing.", completion = "The sooner those Scourge are pushed out of the Fungal Vale, the sooner we can heal it.\n\nThank you, {name}.", objectives = "Obtain Control Runes from Dark Cultists and Shadowmages, then use the Overcharged Mote on them to destroy 3 Plague Disseminators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27421] = { id = 27421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst Death, Life", description = "Scourge forces have made it a point to ensure that nothing survives in the Fungal Vale - all you will find are husks of rotted mushrooms and scorched grasses.  The three corners of the vale are home to three large ziggurats, which they use to reanimate their dead and summon new soldiers to the battlefield.\n\nYet even in this evil, lifeless place, life finds a way to flourish.  Take my seeds and plant them in the centers of these ziggurats.  Prove to them that life will prevail.", completion = "Even if the flowers died out shortly after they bloomed, they proved our point to the Scourge: they are losing, and we are winning.\n\nThank you for your assistance.", objectives = "Use Rayne's Seeds in the center of the three ziggurats in the Fungal Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27422] = { id = 27422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A City Under Siege", description = "We will never control the Eastern Plaguelands if we do not control Stratholme. Not only is it a point of incredible strategic importance, it also houses our enemies' leaders - Balnazzar and Lord Aurius Rivendare. Their Risen and Scourge armies threaten to erase all the progress we've made.\n\nThe Argent Crusade is well-suited to this task. Travel west through Stratholme's main gate and speak with Packmaster Stonebruiser. He will direct you further.", completion = "What a relief it is to see an able-bodied soldier that's on our side! There's plenty for ye to do around here, {race}.", objectives = "Speak to Packmaster Stonebruiser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27423] = { id = 27423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resistance is Futile", description = "<The F.C.D. buzzes.>\n\nThis is Commander Lorna Crowley of the Gilneas Liberation Front. If you are hearing this message then you know that the Alliance once again controls Gilneas. Lay down your weapons and surrender. Failure to comply will result in your death.\n\nOur forces have locked on to your position and will arrive shortly. Resistance is futile.", progress = "Surrender? Coward talk...", completion = "No time to bask in the battle glory, {name}. We have a job to do. I have no doubt more of those beasts are on the way.", objectives = "Kill 20 Worgen Combatants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27424] = { id = 27424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny {race}, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good {race}. Me miss things very much. Me like you now.", objectives = "Collect Overlord Mok'Morokk's grog, snuff and strongbox from Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27425] = { id = 27425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help.", objectives = "Report to Captain Darill at North Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27426] = { id = 27426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list.", objectives = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them into the Grimtotem Battle Plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27427] = { id = 27427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.", objectives = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27428] = { id = 27428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?", objectives = "Speak with Tabetha at her farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27429] = { id = 27429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that.", objectives = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27430] = { id = 27430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed.", objectives = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27431] = { id = 27431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tipping the Balance", description = "<Harrison grins.>\n\nThat's it, {name}. The pieces we need are hidden in these statues!\n\nThey look to be a bit off balance as is. Maybe just a little nudge...\n\nI must say, your field work is coming along nicely. If you applied yourself, you could make a fine archaeologist one day.", completion = "Talk about bringing the house down...", objectives = "Speak to Harrison Jones in the Chamber of the Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27432] = { id = 27432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr the Outcast", description = "Can you believe that, after all the trouble we have in the Plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from our graveyards, then take them back to their evil, dead troll hideout--the Undercroft to the southwest.\n\nGo there and take out Zaeldarr, {name}.  I'm sick to death of his mischief!", progress = "Did you find the hideout, {name}?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!", objectives = "Obtain Zaeldarr's Head from Zaeldarr the Outcast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27433] = { id = 27433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredderectomy", description = "Our tanks have to pull back, and that means repairs in the field.\n\nSmash up summa them diamond-bladed shredders those wee green monsters are using to fell the trees along the coast, and bring me a heap of leftover shredder parts. We'll bang together sumthun' to get our tanks movin' again.", progress = "What'd you get me, {name}?", completion = "Oh aye, tha's the stuff! A good engineer can make anything outta just about anything.\n\nThis here doo-jicker could recouple a busted cylinder casing... Oh! And who doesn't want a dongle? ...And you can fashion this jobby into a ... thing.\n\n<Flintlocke sticks one of the grease-smeared engine parts into his mouth.>\n\nYep, perfect.", objectives = "Destroy Diamond-Blade Shredders to collect 5 Abused Shredder Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27434] = { id = 27434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adept's Path", description = "Your time as an apprentice has come to an end, {name}. You are ready to advance to the rank of adept, to become a full blood knight in service to Silvermoon.\n\nTo honor your accomplishments, the warchief has commissioned his personal smith to forge a weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists there.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I don't know how you came by such a large supply of moonsteel, {name}, but I haven't worked with it in years. It will be both a challenge and a pleasure to create this weapon for you.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27435] = { id = 27435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "Your skills have grown and you are now ready to become a full seer. You have completed your early training with skill and dedication.\n\nTo mark this occasion, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Seer Liwatha mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. I see now why she sent you there. Even the twisted magics gripping the keep could not extinguish the power of these items.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27436] = { id = 27436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "Your skills have grown and you are now ready to become a full seer. You have completed your early training with skill and dedication.\n\nTo mark this occasion, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Shadow-Walker Zuru mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. Artifacts from the keep are reputed to possess much hidden power and your efforts are proof that the tales are true. Your staff will be a masterwork.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27437] = { id = 27437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsaken Faith", description = "You have been a diligent student and servant to our cause. Always use your talents in accord with Lady Sylvanas's wishes and you will be blessed by the shadow.\n\nOur queen has arranged for Orgrimmar's master enchanter to create a powerful staff to recognize your service.\n\nThe materials you will need only come from Shadowfang Keep in the heart of Silverpine Forest. Find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Dark Cleric Cecille mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. I see now why she sent you there. Even the twisted magics gripping the keep could not extinguish the power of these items.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27438] = { id = 27438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Escape", description = "With our mission objective secured, the time has come for us to make our escape. Though Gilneas is lost, with the aid of Godfrey and his lieutenants we will have it back in no time at all.\n\nGo now, {name}. Fly back with Arthura to the Forsaken Front in southern Silverpine Forest. The Banshee Queen awaits your arrival.", completion = "I had no doubt that you would succeed, {name}. I hope you can understand why I kept the true purpose of your mission a secret. Should Crowley and Bloodfang have found out about our plan, they would have surely gotten to Godfrey first and disposed of the body.\n\nStand by, {name}. The time of their rebirth is at hand.", objectives = "Escape the Ruins of Gilneas with Arthura and the corpse of Lord Godfrey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27439] = { id = 27439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staff of the Light", description = "You are quickly becoming a talented servant of the Light and of Silvermoon, {name}. Your loyalty to our people and to the Horde are exemplary.\n\nIn recognition of your dedication, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Tyelis mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. Few would venture into the keep, even to retrieve such valuable things. Your new staff will be a fitting reward for your bravery.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27440] = { id = 27440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls, Ogres, and Orcs, Oh My!", description = "The black dragonkin Overlord Wyrmthalak oversees the forces of the Lower Spire, who are nearly prepared to launch a full assault on the Dark Iron Dwarves far below. We simply cannot allow the black dragonflight to gain control of the mountain!\n\nYou must kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Their deaths will cause the army's momentum to grind to a halt and will buy us valuable time.", progress = "These are not mindless beasts you are up against, {race}. It is a massive army backed by the ruthless black dragonflight. Exercise caution in these corridors.", completion = "Pardon my saying so, but I am surprised you completed the task set out before you alive. Those monsters were responsible for the deaths of countless thousands, a great many of them heroes still spoken highly of to this day.\n\nYou have earned my respect and a reward for your courage.", objectives = "Kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27441] = { id = 27441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seer's Staff", description = "I hear that word of your deeds in service to the Horde has even reached the ears of the warchief. He has agreed to allow Orgrimmar's master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", progress = "Did you bring the materials I'll need for your weapon?", completion = "You must be the {class} that Brother Silverhallow mentioned. Welcome, {name}. Let me see those materials you gathered from halfway around the world. They seem well worth the travel and you will not be disappointed with your staff.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27442] = { id = 27442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", completion = "Your aid is most timely, {name}.", objectives = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27443] = { id = 27443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City for further instructions.", completion = "Your aid is most timely, {name}.", objectives = "Speak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27444] = { id = 27444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Warchief", description = "Rend Blackhand was the son of an Orc Warchief. His father was slain by Orgrim Doomhammer, who became the new Warchief over the young orc. Rend now stands as the supposed leader of a false Horde of Blackrock orcs, backed by Nefarian and his army of dragons.\n\nThe fool claims that the Horde is also his by birthright, and threatens to take it by force! We cannot allow this to occur in light of his master's influence. Find him in the Upper Spire and bring an end to the false warchief, {class}.", completion = "You saw Nefarian when you fought Rend?\n\n<Acride sighs.>\n\nI wish I had accompanied you, then. I could have faced him unaware, outside his lair...but no matter. Nefarian will die by my claw.\n\nYou've done well.", objectives = "Kill Warchief Rend Blackhand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27445] = { id = 27445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisath, Hand of Nefarian", description = "Nefarian makes his domain further up the mountain in Blackwing Lair. Though there is a way in through the Upper Spire, we may bring a far larger force if we use the teleportation orb close by. However, we cannot teleport until we brand ourselves with a different orb.\n\nDrakkisath, General of Nefarian's armies, personally guards this second orb. Eliminate him and secure his orb for our use. You will find him in the Spire Throne within the Upper Spire.", completion = "Excellent! It is only a matter of time before the son of Deathwing feels my claws.", objectives = "Kill General Drakkisath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27446] = { id = 27446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris is Calling", description = "Heya, {name}, Kelsey Steelspark down in Tanaris left a message for you. She says that the gnomes down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.", completion = "Greetings and salutations, friend. Welcome to Tanaris!", objectives = "Speak with Kelsey Steelspark at Gadgetzan in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27447] = { id = 27447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaris is Calling", description = "Heya, {name}, Megs Dreadshredder down in Tanaris left a message for you. She says that the goblins down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.\n\nBesides, that Megs is a hottie!", completion = "Well hello there, {class}. Welcome to Tanaris!", objectives = "Speak with Megs Dreadshredder at Gadgetzan in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27448] = { id = 27448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trek Continues", description = "I believe the horses are ready.  Argus Highbeacon, the gentleman who works with the Argent Crusade, spoke with me earlier.  I understand he will be coming with us... that's great!  I'll make room for him.\n\nI know that you are busy, so there's no hurry.  Whenever you're ready, hop into the caravan, and we will proceed to the next tower.", progress = "Once we get to Light's Shield Tower, the boys can head over to Light's Hope Chapel.  It's close enough that they can walk.", completion = "We've enjoyed having you ride with us, {name}.  Hopefully, once Gidwin and Tarenar join the Argent Crusade, we can continue to travel together.", objectives = "Board Fiona's Caravan when you are ready to move to the next tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27449] = { id = 27449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Strength", description = "My name is Vex'tul, and I have watched you fight, {race}.  You are strong.\n\nYou killed my master, Zaeldarr, but this does not bother me.  I value strength over any loyalty that I held for him.  I value strength over anything else.\n\nProve to me one final time your strength, {race}.  Do so, and I will lend you MY strength for whatever purpose you may desire.", progress = "Honor means nothing.  Strength is everything.", completion = "Yes, you are indeed strong... and I submit to you.\n\nI will join you and your friend, the worgen.  My strength is yours.", objectives = "Pass Vex'tul's test of strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27450] = { id = 27450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frederick's Fish Fancy", description = "I love the sea.  Yes, it was I, Frederick Calston, who introduced the sea life to that lake in the southwest.  I had hoped to provide the Crusade with a source of fresh food from within the borders of the Plaguelands.\n\nHowever, some of the fish turned out to be predators, and they now terrorize the other animals.  If we're not careful, they will kill them all!\n\nSwim down to the bottom of the scar and save some snails, crabs, and pufferfish before it's too late.", progress = "Did... did you bring the fish?", completion = "Hmm... they didn't survive the trip out of the water as well as I had hoped.\n\nOh well!  Seafood salad for Frederick tonight!", objectives = "Obtain 8 Plague Puffers, 8 Infectis Inchers, and 8 Infectis Scuttlers from the Infectis Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27451] = { id = 27451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Kill With Purpose", description = "Greetings, stranger!  You've entered the heart of the Plaguelands.  I hope you brought your undead-killing gear with you.\n\nThe plague spreads more slowly these days, so the Cult of the Damned has stepped up production in order to keep the land brown and dead, as they like it.  I've got a plan to stop them.  Take my mortar and pestle, and use it on living rot from the undead creatures in Corin's Crossing to the southeast.  We're going to make a little present for the cultists!", progress = "How are things looking in Corin's Crossing?", completion = "Hello!  It's me.  Hope you don't mind a little home-brewed magic to allow me to communicate with you in the field.  It'll save us both some time.\n\nWe're going to incorporate that living rot into a mixture that'll ruin their next batch of plague.  That'll show them!", objectives = "Travel to Corin's Crossing to the south and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27452] = { id = 27452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Garb", description = "Some of my counterparts have told me that the land wants to heal, but several high-ranking undead - along with the Cult of the Damned - are not allowing it to.  That means we have to stop them!  I've got a plan, but first, you're going to need a cultist disguise.\n\nHead southeast into Corin's Crossing, and take the clothing from the human cultists that roam through the town.  I'll contact you when you've completed this step.", progress = "Everything going alright so far, {name}?", completion = "You've got both pieces!  Good.  These will help when trying to sneak into their death camp.", objectives = "Obtain Death Cultist Headwear and Death Cultist Robes from cultists within Corin's Crossing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27453] = { id = 27453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catalysm", description = "Coagulated rot is potent on its own, but we need something to activate its concealed powers... a catalyst.  You can find just such a catalyst to the south, in Lake Mereldar.\n\nIf you look down, you'll notice that I slipped a set of flasks into your bags while you weren't looking.  These flasks can be used on the water elementals in the lake.  The living, corrupted water that flows through their bodies will be the perfect catalyst!", progress = "We're nearly ready to strike, {name}.", completion = "Uh oh... it looks like we may have gathered a little too much coagulated rot.  Oh well, we'll just have to improvise, then!\n\nWhat could possibly go wrong?", objectives = "Use Betina's Flasks on living elementals within Lake Mereldar to obtain 8 Active Liquid Plague Agents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27454] = { id = 27454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Drop in the Bucket", description = "Now, mix a tiny amount of rot into the water, and mix thoroughly.  There, that's it.  This solution will still be very powerful, and we only need a little bit of it.\n\nOn the lake's southeastern border, you will find a plague cauldron with several cultists nearby.  Put on your cultist disguise, then approach the cauldron and put in ONE DROP of the solution you made.  No more, or you may risk your very life!", completion = "It should take them weeks to get their operation running again.  Thank you, {name}.", objectives = "Use your Death Cultist Disguise to enter the Death Cultist Base Camp, then put Betina's mixture into the Mereldar Plague Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27455] = { id = 27455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boys Will Be Boys", description = "As soon as we arrived here at Light's Shield Tower, those two lunkhead paladins ran off to Light's Hope Chapel.  It's still a ways away, but if we're going to follow Argus along his tour of the towers, this is about as close as we're going to get.\n\nCheck in on them and make sure they're alright?  I know they can handle themselves, but still, it'd make me feel better to know that you were watching over them while I'm stuck here with the caravan.", completion = "I can't believe it.  We're literally FEET away from becoming sworn members of the Argent Crusade.\n\nWe'd be in there already if it weren't for Tarenar's dallying.  If he doesn't quit chatting with the locals soon, I'm going to head in there myself.", objectives = "Find Gidwin Goldbraids at Light's Hope Chapel in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27456] = { id = 27456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Some Grub(s)", description = "We have problems maintaining our food supplies here in the far east.\n\nAround here, the only manner of beast unaffected by the ravages of the plague are the carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. We will need several hundred more pounds to be fully-stocked.\n\nWhile you can find carrion worms all over the Plaguelands, they can be found in particularly high density to the south of the chapel.  And remember: larger worms mean more meat.", progress = "You will grow to tolerate the taste, {race}.  I did.", completion = "May the Earthmother watch over you! Bless you, young one.", objectives = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest 15 Slabs of Carrion Worm Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27457] = { id = 27457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opportune Alliance", description = "With your contributions to the food stores, my current assignment is complete.\n\nI will be heading north, to the Plaguewood, next.  I understand you may be headed in the same direction.\n\nDo you mind if I join you on the road?\n\nI will head northwest, to Eastwall Tower.  If you're interested in teaming up, you can meet up with me there.", completion = "You brought us a shaman!  From the Earthen Ring, no less!\n\nI have no idea how we'll fit him in the caravan, but we'll find a way.  Welcome aboard, Rimblat Earthshatter!", objectives = "Check in with Fiona at Eastwall Tower in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27458] = { id = 27458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smokey and the Bandage", description = "Hey there!  Interested in makin' a buck?\n\nI need to get a bandage.  Well, actually, I got a friend who needs to get a bandage.  Well actually... let's just say it's complicated, but if you go get this bandage, you make money.  And so do I.  And my friend.  Possibly other people.\n\nStephen Browman used to own the mill to the north, now he's dead.  A zombie.  The guy at the top wants to have the wrappings from Browman's body.\n\nWhat's the matter, you don't like money?", progress = "You've been fightin' undead.  Did ya find Browman?", completion = "Well well well!  Someone who goes and gets things done!  Here's your cut, chief.  I'll be seein' you around.", objectives = "Obtain Browman's Wrappings from Stephen Browman at Browman's Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27459] = { id = 27459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brotherhood of Light", description = "The Brotherhood of Light has a history of brash, thoughtless decisions.  They bridged a gap between the Scarlet Crusade and the Argent Dawn.  They were among the first to plunge into Northrend, while many of us lingered behind.\n\nHowever, they also have a history of getting results, which I respect.  They fight on two fronts now: one battle in Stratholme, and another, more immediate battle to the south at Tyr's Hand.\n\nI suggest you speak with Angela Dosantos at Tyr's Hand.  You may be of service.", completion = "A {class}!  Just what we needed.  Your arrival couldn't have been more timely.", objectives = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27460] = { id = 27460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Landing", description = "We were only given one hundred men to complete this mission, and we're already down by one.  Our scout was sent into the enemy stronghold to clear out some of the guards that patrol the area, and to send off a flare so we could enter with a coordinated attack.  Our ninety-nine remaining men lie at the ready, waiting for that flare.  I need a talented {class} like you to sneak into Tyr's Hand, take out as many of their guards as possible, and then set off that flare.\n\nAre you up to it?", completion = "The flare is fully assembled, and the matches lie unused next to the fuse.\n\nThe fallen Argent centurion got much closer to setting off this flare than you had guessed.", objectives = "Kill any 10 Scarlet Crusade creatures within Tyr's Hand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27461] = { id = 27461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Take the Abbey", description = "The Scarlet Crusade maintains a well-fortified abbey in the lower western tier of Tyr's Hand.  The abbey will need to be secured before proceeding any further into the stronghold.", completion = "Well met, {name}.  Can I trust you to assist me in taking this abbey away from these abominations?", objectives = "Report to Commander Eligor Dawnbringer outside the abbey at Tyr's Hand in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27462] = { id = 27462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Take the Barracks", description = "One of the key fortifications within Tyr's Hand is the barracks, which lies right next to this flare.  The Brotherhood of Light and their centurions will need all the help they can get in sacking it.", completion = "I'll be handling things from here, {class}.\n\nFine, you want an assignment?  I suppose I can afford to send you in on a mission or two.", objectives = "Report to Crusade Commander Korfax in front of the Barracks at Tyr's Hand in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27463] = { id = 27463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boyhood Dream", description = "I've always wanted to join the Crusade.  It's the reason I became a paladin.  Years of practice, honing my craft... I'm finally ready.\n\nTarenar thinks he's ready, too, but I'm not sure.  He's a bit of a showboat, and he never took his lessons seriously.  Still, we promised we'd do this together, and here we are.\n\nShall we head into the chapel now?", completion = "Welcome to Light's Hope Chapel.\n\nYou wish to join the Crusade?  Very well.  We have plenty of tasks for new recruits.\n\nBut first, a test.", objectives = "Speak with Lord Maxwell Tyrosus within Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27464] = { id = 27464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: The Trial of the Crypt", description = "Behind our chapel, you will find a small crypt.  Interred within are the bodies of our fallen heroes; those who gave their lives in the war against the Scourge.\n\nTheir spirits are at peace, but they return intermittently to test new members of the order.\n\nThe three of you may test together.  Enter the crypt, then read from this scroll.  Lord Raymond George - my predecessor - will preside over your test.", progress = "Your test is not yet complete.", completion = "Remember that your ancestors always watch over you.  As a brother of the Argent Crusade, you will join a family that has a long line of such fallen ancestors.  Their vigil and protection will be your strength as you press forward against the Scourge.\n\nCongratulations Tarenar, Gidwin, and {name}.  Welcome to the Argent Crusade.", objectives = "Enter the Crypt behind Light's Hope Chapel, read from the Argent Scroll, then complete his test.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27465] = { id = 27465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: The Noxious Glade", description = "Browman's Mill, to the north, is infested with undead.  The Noxious Glade, even farther to the north, is even more heavily infested.  Despite their proximity to our chapel, we have been unable to completely remove them.\n\nVigilance is key.  Travel into the Noxious Vale and slay as many undead as you can find... and the cultists that roam among them.\n\nWhile there, make sure to avoid Garginox, the flesh giant that roams the vale.  I suspect you are not strong enough to defeat him.", completion = "You've returned sooner than I expected.  Excellent.\n\nWe will continue our path into the north.  Next, you will be completing a similar task - this time, in Northdale.", objectives = "Slay 16 Scourge and 8 Cultists within Browman Mill and the Noxious Glade. Return to Light's Hope Chapel if Tarenar or Gidwin is slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27466] = { id = 27466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Call: Northdale", description = "Tyrosus has given us our next task: slaying more undead in Northdale.  Gidwin is excited to move forward, but I think we should show a little more caution.\n\nLet's meet up with Fiona.  She should be at the next tower by now... Eastwall Tower, I think it's called.  It's close by, to the northwest of Light's Hope.  We can rest there, and plan our attack on Northdale.", completion = "Hello, {name}!  Glad to see you've rejoined the caravan!\n\nTarenar and Gidwin arrived here before you.  Tarenar's just right there, and Gidwin's... well... he's in a little bit of a mood right now.  I think he's in the tower.", objectives = "Speak with Fiona at Eastwall Tower in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27467] = { id = 27467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Blades", description = "The Noxious Glade is a quagmire, both literally and figuratively.  There's enough Scourge up there to give us trouble for the rest of both of our lifetimes.\n\nThey can re-animate the weaker ones when they die, {name}.  They will never stop coming if we don't do something.\n\nTake these blades and drive them through the corpses of any Scourge troopers you find.  The blade is simple, but its enchantment will prevent the dead bones from being reanimated.  Forever.", completion = "Our duty for the day is done.\n\nIt is only a matter of time before we defeat the Scourge.  Today, we made progress.", objectives = "Bury the Light-Touched Blades in the bodies of 10 Slain Scourge Troopers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27468] = { id = 27468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege Tank Rescue", description = "One by one, we're gonna have to pull our siege tanks outta the muck. Take these 'ere spare parts you've collected and give 'em to a siege tank commander who's perched on one o'those banged-up machines.\n\nThen defend the tank while engineers repair the blasted thing.\n\nGo an' make me proud, {class}!", progress = "Rocks an' stumps an' hills an' mud... Bah.\n\nI hate nature.", completion = "Yep, one more tank limpin' back home for repairs.\n\nAll these trees an' stumps an' mud an' rock - you couldnae drive a golfball into this turf, much less a tank.\n\nWe're gonna need a new approach.", objectives = "Speak with a Siege Tank Commander standing on top of a wrecked Highbank Siege Tank. Defend the tank while engineers make repairs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27469] = { id = 27469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends on The Other Side", description = "I come with news from Blackrock Spire. We have a new visitor. His name is Acride.\n\nHe seeks people of strength, people of intelligence, of dexterity. You ought to go to Blackrock Spire and speak with him.", completion = "Hello, what is your business in a place like this?\n\nI'm sorry, who sent you? I'm afraid I've never heard of such a dwarf.", objectives = "Find Acride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
